(async () => {
  let updated = 0, skipped = 0;
  for (const u of UPDATES) {
    const { data: existing, error: selErr } = await supabase
      .from('blog_posts')
      .select('slug,content')
      .eq('slug', u.slug)
      .maybeSingle();

    if (selErr) {
      console.error(`❌ Chyba pri kontrole ${u.slug}:`, selErr.message);
      continue;
    }
    if (!existing) {
      console.error(`⚠️  ${u.slug} sa v DB nenašiel, preskakujem.`);
      continue;
    }
    if (existing.content && (existing.content.includes('<strong>Pripravuješ sa') || existing.content.includes('<strong>Zaujíma ťa'))) {
      console.log(`⏭  ${u.slug} už má prelinkovanie, preskakujem.`);
      skipped++;
      continue;
    }

    const { error: updErr } = await supabase.from('blog_posts').update({ content: u.content, content_cs: u.content_cs }).eq('slug', u.slug);
    if (updErr) {
      console.error(`❌ Chyba pri update ${u.slug}:`, updErr.message);
      continue;
    }
    console.log(`✅ Prelinkované: ${u.slug}`);
    updated++;
  }
  console.log(`\nHotovo. Aktualizovaných: ${updated}, preskočených (už mali): ${skipped}, spolu: ${UPDATES.length}.`);
})();
